"use client";
import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { X, Key, Save, Loader2, CheckCircle2, ShieldCheck, Shield, Copy, QrCode } from 'lucide-react';
import { useAuthStore } from '../store/authStore';
import { supabase } from '../lib/supabase';
import { cn } from '../lib/utils';

interface IntegrationModalProps {
  channelKey: string | null;
  isOpen: boolean;
  onClose: () => void;
}

export function IntegrationModal({ channelKey, isOpen, onClose }: IntegrationModalProps) {
  const updateChannelConnection = useAuthStore(s => s.updateChannelConnection);
  const connectedChannels = useAuthStore(s => s.connectedChannels);
  
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Form State
  const [formData, setFormData] = useState<Record<string, string>>({});
  
  // Snippet Copy State
  const [copied, setCopied] = useState(false);
  const user = useAuthStore(s => s.user);

  // Outreach WhatsApp Engine State
  const [outreachConnection, setOutreachConnection] = useState<any>(null);
  const [pairingLoading, setPairingLoading] = useState(false);

  const startWhatsAppPairing = async () => {
    setPairingLoading(true);
    try {
      // Create a pending connection record so the Node backend starts the Baileys session
      const { error } = await supabase
        .from('outreach_channel_connections')
        .upsert({ 
          channel: 'whatsapp', 
          status: 'connecting',
          updated_at: new Date().toISOString()
        }, { onConflict: 'channel' });
      
      if (error) throw error;
    } catch (err: any) {
      console.error('Failed to start WhatsApp pairing', err);
    } finally {
      setPairingLoading(false);
    }
  };

  useEffect(() => {
    if (!isOpen || channelKey !== 'WhatsApp') return;

    // Fetch initial state
    supabase
      .from('outreach_channel_connections')
      .select('*')
      .eq('channel', 'whatsapp')
      .single()
      .then(({ data }) => setOutreachConnection(data));

    // Subscribe to realtime updates
    const sub = supabase
      .channel('whatsapp_qr_updates')
      .on('postgres_changes', { 
        event: '*', 
        schema: 'public', 
        table: 'outreach_channel_connections',
        filter: 'channel=eq.whatsapp'
      }, (payload) => {
        setOutreachConnection(payload.new);
      })
      .subscribe();

    return () => {
      supabase.removeChannel(sub);
    };
  }, [isOpen, channelKey]);
  
  const chatSnippet = `<script>
  window.STARX_CONFIG = {
    clientId: "${user?.id || 'demo_id'}",
    theme: "dark"
  };
</script>
<script src="https://cdn.starx-flow.com/widget.js" async></script>`;

  const handleCopySnippet = () => {
    navigator.clipboard.writeText(chatSnippet);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  // WhatsApp connection state helpers
  const whatsappChannel = connectedChannels.find(c => c.channelKey === 'WhatsApp');
  const isWhatsAppConnected = whatsappChannel?.isConnected || false;
  const whatsappCreds = whatsappChannel?.credentials || {};

  useEffect(() => {
    if (isOpen && channelKey) {
      setSuccess(false);
      setError(null);
      
      // Pre-fill existing credentials if they exist
      const existing = connectedChannels.find(c => c.channelKey === channelKey);
      if (existing && existing.credentials) {
        setFormData(existing.credentials);
      } else {
        setFormData({});
      }
    }
  }, [isOpen, channelKey, connectedChannels]);

  // Handle Escape Key
  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) onClose();
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [isOpen, onClose]);

  if (!isOpen || !channelKey) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    const { error: submitError } = await updateChannelConnection(channelKey, true, formData);
    
    setLoading(false);
    
    if (submitError) {
      setError(submitError);
    } else {
      setSuccess(true);
      setTimeout(() => {
        onClose();
      }, 1500);
    }
  };

  const handleDisconnect = async () => {
    if (!window.confirm(`Are you sure you want to disconnect ${channelKey}?`)) {
      return;
    }

    setLoading(true);
    setError(null);

    const { error: disconnectError } = await updateChannelConnection(channelKey, false, {});

    setLoading(false);
    
    if (disconnectError) {
      setError(disconnectError);
    } else {
      setSuccess(true);
      setTimeout(() => {
        onClose();
      }, 1500);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData(prev => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const renderFields = () => {
    switch (channelKey) {
      case 'WhatsApp':
        if (isWhatsAppConnected && whatsappCreds.phone_number_id) {
          return (
            <div className="flex flex-col items-center justify-center py-4 text-center space-y-4">
              <div className="relative">
                <div className="w-16 h-16 rounded-full bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center">
                  <ShieldCheck className="w-8 h-8 text-emerald-400" />
                </div>
                <span className="absolute bottom-0 right-0 w-4 h-4 bg-emerald-500 border-2 border-[#0a0a0a] rounded-full animate-pulse" />
              </div>
              <div className="space-y-1">
                <h4 className="text-white font-bold text-base">Meta API Connected</h4>
                <p className="text-emerald-400 font-mono text-sm">Phone ID: {whatsappCreds.phone_number_id}</p>
              </div>
            </div>
          );
        }

        return (
          <div className="space-y-4">
            {outreachConnection?.status === 'connected' ? (
              <div className="flex flex-col items-center justify-center py-4 text-center space-y-4">
                <div className="relative">
                  <div className="w-16 h-16 rounded-full bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center">
                    <ShieldCheck className="w-8 h-8 text-emerald-400" />
                  </div>
                  <span className="absolute bottom-0 right-0 w-4 h-4 bg-emerald-500 border-2 border-[#0a0a0a] rounded-full animate-pulse" />
                </div>
                <div className="space-y-1">
                  <h4 className="text-white font-bold text-base">WhatsApp Web Connected</h4>
                  <p className="text-emerald-400 text-sm">Session active and listening.</p>
                </div>
              </div>
            ) : outreachConnection?.qr_code_data ? (
              <div className="rounded-[1.15rem] border border-[color:var(--border-subtle)] bg-[color:var(--surface-0)] p-5 text-center">
                <div className="mb-4 flex items-center justify-center gap-2 text-[color:var(--text-dim)]">
                  <QrCode size={16} />
                  <span className="text-xs uppercase tracking-[0.16em]">Pairing QR</span>
                </div>
                <img
                  src={outreachConnection.qr_code_data}
                  alt="WhatsApp QR code"
                  className="mx-auto max-w-[240px] rounded-[1rem] border border-[color:var(--border-subtle)] bg-white p-3"
                />
                <p className="mt-4 text-sm text-[color:var(--text-muted)]">
                  Open WhatsApp on your phone, go to linked devices, and scan this code.
                </p>
              </div>
            ) : (
              <div className="rounded-[1.15rem] border border-[color:var(--border-subtle)] bg-[color:var(--surface-0)] p-5 text-center">
                <QrCode size={32} className="mx-auto text-zinc-500 mb-3" />
                <h4 className="text-white font-bold mb-2">WhatsApp Autonomous Engine</h4>
                <p className="text-sm text-zinc-400 mb-4">
                  Connect via QR code to enable the Baileys autonomous outreach engine.
                </p>
                <button
                  type="button"
                  onClick={startWhatsAppPairing}
                  disabled={pairingLoading}
                  className="bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 px-4 py-2 rounded-lg text-sm font-semibold hover:bg-emerald-500/20 transition-colors"
                >
                  {pairingLoading ? 'Starting Node Engine...' : 'Generate QR Code'}
                </button>
              </div>
            )}
            
            <div className="mt-4 pt-4 border-t border-white/5">
              <p className="text-xs text-zinc-500 font-semibold mb-3 uppercase tracking-wider">Alternative: Meta Cloud API</p>
              <div className="space-y-1.5 mb-3">
                <label className="text-xs font-medium text-zinc-400">Meta Access Token</label>
                <input 
                  type="password" name="access_token" value={formData.access_token || ''} onChange={handleChange}
                  placeholder="EAALXxxxxxxxxxxxx..." className="w-full bg-[#111] border border-white/10 rounded-lg px-4 py-2 text-sm text-white outline-none focus:border-emerald-500/50 font-mono"
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-medium text-zinc-400">Phone Number ID</label>
                <input 
                  type="text" name="phone_number_id" value={formData.phone_number_id || ''} onChange={handleChange}
                  placeholder="123456789012345" className="w-full bg-[#111] border border-white/10 rounded-lg px-4 py-2 text-sm text-white outline-none focus:border-emerald-500/50 font-mono"
                />
              </div>
            </div>
          </div>
        );
      case 'Instagram':
        return (
          <>
            <div className="space-y-1.5">
              <label className="text-xs font-medium text-zinc-400">Instagram Account ID</label>
              <input 
                type="text" name="ig_account_id" value={formData.ig_account_id || ''} onChange={handleChange} required
                placeholder="e.g. 1784XXXXXXXX" className="w-full bg-[#111] border border-white/10 rounded-lg px-4 py-2.5 text-sm text-white outline-none focus:border-pink-500/50"
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-xs font-medium text-zinc-400">Meta Access Token</label>
              <input 
                type="password" name="access_token" value={formData.access_token || ''} onChange={handleChange} required
                placeholder="EAAO..." className="w-full bg-[#111] border border-white/10 rounded-lg px-4 py-2.5 text-sm text-white outline-none focus:border-pink-500/50"
              />
            </div>
          </>
        );
      case 'SMS':
        return (
          <>
            <div className="space-y-1.5">
              <label className="text-xs font-medium text-zinc-400">Twilio Account SID</label>
              <input 
                type="text" name="twilio_sid" value={formData.twilio_sid || ''} onChange={handleChange} required
                placeholder="ACXXXXXXXXXXXXXXXXX" className="w-full bg-[#111] border border-white/10 rounded-lg px-4 py-2.5 text-sm text-white outline-none focus:border-blue-500/50"
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-xs font-medium text-zinc-400">Twilio Auth Token</label>
              <input 
                type="password" name="twilio_token" value={formData.twilio_token || ''} onChange={handleChange} required
                placeholder="****************" className="w-full bg-[#111] border border-white/10 rounded-lg px-4 py-2.5 text-sm text-white outline-none focus:border-blue-500/50"
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-xs font-medium text-zinc-400">Twilio Phone Number</label>
              <input 
                type="text" name="twilio_phone" value={formData.twilio_phone || ''} onChange={handleChange} required
                placeholder="+1234567890" className="w-full bg-[#111] border border-white/10 rounded-lg px-4 py-2.5 text-sm text-white outline-none focus:border-blue-500/50"
              />
            </div>
          </>
        );
      case 'Web':
        return (
          <div className="space-y-4">
            <div className="bg-cyan-500/10 border border-cyan-500/20 p-4 rounded-xl space-y-3">
              <div className="flex items-start gap-3">
                <div className="w-1.5 h-1.5 bg-cyan-400 rounded-full mt-1.5" />
                <div className="space-y-1">
                  <h4 className="text-sm font-bold text-cyan-50">Embed the Chat Widget</h4>
                  <p className="text-xs text-cyan-200/70 leading-relaxed">
                    Copy the snippet below and paste it just before the closing <code>&lt;/body&gt;</code> tag of your website.
                  </p>
                </div>
              </div>
              <div className="relative group">
                <pre className="bg-[#050505] p-4 rounded-lg overflow-x-auto text-[11px] text-zinc-300 font-mono border border-white/10 leading-relaxed">
                  <code>{chatSnippet}</code>
                </pre>
                <button 
                  type="button"
                  onClick={handleCopySnippet}
                  className="absolute top-2 right-2 p-2 bg-white/10 hover:bg-white/20 rounded-md transition-colors flex items-center justify-center backdrop-blur-sm border border-white/10"
                >
                  {copied ? <CheckCircle2 className="w-4 h-4 text-emerald-400" /> : <Copy className="w-4 h-4 text-white" />}
                </button>
              </div>
            </div>
          </div>
        );
      default:
        return (
          <div className="space-y-1.5">
            <label className="text-xs font-medium text-zinc-400">API Key / Token</label>
            <input 
              type="password" name="api_key" value={formData.api_key || ''} onChange={handleChange} required
              placeholder="Enter API Key" className="w-full bg-[#111] border border-white/10 rounded-lg px-4 py-2.5 text-sm text-white outline-none focus:border-emerald-500/50"
            />
          </div>
        );
    }
  };

  const isConnected = channelKey === 'WhatsApp' ? isWhatsAppConnected : connectedChannels.find(c => c.channelKey === channelKey)?.isConnected;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
        onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}
        className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md"
      >
        <motion.div
          initial={{ scale: 0.95, y: 20 }} animate={{ scale: 1, y: 0 }} exit={{ scale: 0.95, y: 20 }}
          className="w-full max-w-md glass-panel rounded-2xl overflow-hidden"
        >
          {/* Header */}
          <div className="flex items-center justify-between p-5 border-b border-white/5 bg-white/[0.02]">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-lg bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center">
                <Key className="w-5 h-5 text-emerald-400" />
              </div>
              <div>
                <h3 className="text-base font-bold text-white">
                  {channelKey === 'WhatsApp' ? 'WhatsApp (Meta API)' : `Connect ${channelKey}`}
                </h3>
                <p className="text-xs text-zinc-400">
                  {isConnected ? 'Configuration linked' : 'Enter your API credentials'}
                </p>
              </div>
            </div>
            <button onClick={onClose} className="text-zinc-500 hover:text-white transition-colors">
              <X className="w-5 h-5" />
            </button>
          </div>

          {/* Body */}
          <form onSubmit={handleSubmit} className="p-6 space-y-5">
            {error && (
              <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-lg text-xs text-red-400">
                {error}
              </div>
            )}
            
            {success ? (
              <div className="flex flex-col items-center justify-center py-6 text-center">
                <CheckCircle2 className="w-12 h-12 text-emerald-400 mb-3" />
                <h4 className="text-white font-bold text-lg mb-1">
                  {isConnected ? 'Successfully Disconnected' : 'Successfully Connected'}
                </h4>
                <p className="text-zinc-400 text-xs">
                  {isConnected ? 'Session removed.' : 'Your credentials have been securely stored.'}
                </p>
              </div>
            ) : (
              <>
                {renderFields()}
                {(!isConnected) && (
                  <div className="bg-white/[0.02] border border-white/5 p-3 rounded-lg flex gap-2 items-start mt-2">
                    <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full mt-1.5 flex-shrink-0" />
                    <p className="text-[10px] text-zinc-500 leading-relaxed">
                      Your credentials are encrypted and stored securely. We will never share these keys with third parties.
                    </p>
                  </div>
                )}
              </>
            )}

            {!success && (
              <div className="pt-2">
                {isConnected ? (
                  <button
                    type="button"
                    onClick={handleDisconnect}
                    disabled={loading}
                    className="w-full bg-red-500/10 hover:bg-red-500/20 text-red-400 border border-red-500/20 font-semibold text-sm py-3 rounded-xl transition-all flex items-center justify-center gap-2"
                  >
                    {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <X className="w-4 h-4" />}
                    {loading ? 'Disconnecting...' : `Disconnect ${channelKey}`}
                  </button>
                ) : (
                  <button
                    type="submit"
                    disabled={loading}
                    className="w-full bg-emerald-500 hover:bg-emerald-400 text-black font-semibold text-sm py-3 rounded-xl transition-all shadow-[0_0_20px_rgba(16,185,129,0.2)] flex items-center justify-center gap-2"
                  >
                    {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                    {loading ? 'Saving...' : (channelKey === 'Web' ? 'Mark as Embedded' : 'Save & Connect')}
                  </button>
                )}
              </div>
            )}
          </form>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
}
